query:
NODE VALUE `in_degree_sum` SumAgg<INT64> = 0
TABLE `result` { `id` STRING, `total` INT64 }

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`in_degree_sum` += coalesce(`e`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id`, `p`.@`in_degree_sum` INTO `result`
}

FOR `row` IN `result`
RETURN `row`.`id` AS `id`, `row`.`total` AS `total`
